      "source_note": "# Día B — Satélite de Detalle, Congestión & Movilidad\n\nElevación lateral unilateral en cable — 3 × 12–15\nRIR 1 · Descanso 90 s\nÚltimo registro: ninguno comparable.\nHoy: Carga ligera-moderada (~5–9 kg).\nConfiguración: Polea a la altura de la rodilla · agarre por detrás del cuerpo · inclinación lateral de 15° colgándote del poste.\nObjetivo: Torso abierto, pecho proyectado alto; elevación en plano escapular con parada de 1 s arriba mostrando la redondez del deltoides.\nRegistra: Carga, reps y RIR.\n\nKickback diagonal de glúteo en polea baja — 3 × 12–15/lado\nRIR 1 · Descanso 60–90 s\nÚltimo registro: ninguno comparable.\nHoy: Calibrar carga inicial moderada (~7–12 kg con tobillera).\nConfiguración: Polea baja · tobillera fijada · torso flexionado a 45° apoyando antebrazos en la columna con la pelvis neutra.\nObjetivo: Extensión y abducción simultánea (patio de 30° hacia fuera); contracción máxima del glúteo arriba con pierna casi extendida y descenso en 3 s.\nRegistra: Carga por lado, reps y sensación de bombeo.\n\nPeck-deck inverso — 3 × 12–15\nRIR 1 · Descanso 90 s\nÚltimo registro: ninguno comparable.\nHoy: Carga moderada buscando congestión neta en deltoides posterior.\nConfiguración: Asiento regulado para que los brazos queden paralelos al suelo a la altura del hombro.\nObjetivo: Pecho pegado al tapizado, apertura amplia manteniendo los codos ligeramente desbloqueados; sensación de ensanchar la espalda alta.\nRegistra: Carga, reps y RIR.\n\nCossack squat fluida (peso corporal) — 2 × 8–10/lado\nRIR 2 · Descanso 60 s\nÚltimo registro: ninguno comparable.\nHoy: Peso corporal (opcional mancuerna ligera de 4–6 kg al pecho).\nConfiguración: Posición de pies muy amplia (doble ancho de hombros) en zona despejada frente al espejo.\nObjetivo: Descenso profundo y controlado sobre una pierna mientras la otra queda extendida con talón apoyado; cambio de lado fluido a ras de suelo sin subir el centro de gravedad.\nRegistra: Sensaciones de apertura de cadera y fluidez.",
